import base64
import bz2
import lzma
import os
from pathlib import Path
import plistlib
import runpy
import stat
import struct
import subprocess
import tempfile
import unittest
from uuid import UUID
import zlib


SCRIPT = Path(__file__).resolve().parents[2] / "tools" / "dmgx"
DMGX = runpy.run_path(str(SCRIPT))
SECTOR = 512
MTIME = 1712345678
# Generated by Apple's reference encoder from the two strings below.
LZVN_TEXT = b"abc123" * 41
LZVN_STREAM = base64.b64decode("YnZ4bvYAAAAXAAAA5mFiYzEyMzgG8NPjMTIzBgAAAAAAAABidngk")
LZFSE_TEXT = b"The quick brown fox jumps over the lazy dog.\n" * 100
LZFSE_STREAM = base64.b64decode(
    "YnZ4MpQRAAAwAMABAAMAMA0BGJkzDQBwoQAAADeQsA3ncA0AAADXXAMAAADAT/A+fA8AAADf"
    "AwAAAAAAAAAAAAAAAAAA8BMAAAAAAPCYAAAA8BMAAAAAAAAAAABwDQAAcH19ff0oXP8EP8H19f"
    "X19fX3cH39E1xf/wTX19fX1wAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
    "AAVZQ8HyAjbV1YZAn+WDabsrdokmXl0jwZEBAAAAAAAAAACo3sX/R2J2eCQ="
)
# The same FSE payload with its header expanded by Apple's v2 header decoder.
LZFSE_V1_STREAM = zlib.decompress(base64.b64decode(
    "eJxLKqswnCLIwKDJwMBgAMTMQCwDxLxA/Of///+8jAxMExnPMYCAOYMKw20GMTBblAEfECWo"
    "Aga0GcIYQnHK4pahLdAmQe0GKplDCOAOT1EodABibSAURYKhYFIbiYTAUYAMWCOdD35iMrt"
    "6tc1h/tPmzN3aZZ1qcbHKBycywlSsuHf0v3tSWYUKAEnuH3g="
))


def make_udif(tables, sectors):
    """Build a single-segment UDIF with nonzero fork and table offsets."""
    prefix = b"synthetic prefix"
    data = bytearray()
    entries = []
    for first, length, chunks in tables:
        data += b"pad"
        base = len(data)
        mish = bytearray(204)
        struct.pack_into(">4sI3Q", mish, 0, b"mish", 1, first, length, base)
        struct.pack_into(">I", mish, 200, len(chunks) + 1)
        for kind, start, count, packed in chunks:
            mish += struct.pack(">IIQQQQ", kind, 0, start, count, len(data) - base, len(packed))
            data += packed
        mish += struct.pack(">IIQQQQ", 0xffffffff, 0, length, 0, len(data) - base, 0)
        entries.append({"Data": bytes(mish)})
    plist = plistlib.dumps({"resource-fork": {"blkx": entries}})
    trailer = bytearray(512)
    struct.pack_into(">4sIII", trailer, 0, b"koly", 4, 512, 1)
    struct.pack_into(">QQ", trailer, 24, len(prefix), len(data))
    struct.pack_into(">II", trailer, 56, 1, 1)
    struct.pack_into(">QQ", trailer, 216, len(prefix) + len(data), len(plist))
    struct.pack_into(">Q", trailer, 492, sectors)
    return prefix + data + plist + trailer


def fork(size, extents, blocks=None):
    if blocks is None:
        blocks = sum(length for _, length in extents)
    return struct.pack(">QII", size, 0, blocks) + extent_record(extents)


def extent_record(extents):
    return b"".join(struct.pack(">II", *extent) for extent in extents).ljust(64, b"\0")


def btree(records, size, key_compare=0xcf, split=None):
    groups = [records] if split is None else [records[:split], records[split:]]
    result = bytearray(size)
    struct.pack_into(">bBH", result, 8, 1, 0, 3)
    struct.pack_into(">HIIIIHHI", result, 14,
                     1, 1, len(records), 1, len(groups), size, 516, len(groups) + 1)
    result[51] = key_compare
    for number, group in enumerate(groups, 1):
        leaf = bytearray(size)
        struct.pack_into(">IIbBH", leaf, 0,
                         number + 1 if number < len(groups) else 0, number - 1, -1, 1, len(group))
        pos = 14
        for index, (key, body) in enumerate(group):
            struct.pack_into(">H", leaf, size - (index + 1) * 2, pos)
            record = struct.pack(">H", len(key)) + key + body
            if len(record) & 1:
                record += b"\0"
            leaf[pos:pos + len(record)] = record
            pos += len(record)
        struct.pack_into(">H", leaf, size - (len(group) + 1) * 2, pos)
        assert pos <= size - (len(group) + 1) * 2
        result += leaf
    return result


def hfs_volume(unsafe_name=None):
    """Build an HFSX volume with split catalog leaves and fragmented file data."""
    image = bytearray(128 * SECTOR)
    struct.pack_into(">2sH", image, 1024, b"HX", 5)
    struct.pack_into(">II", image, 1024 + 40, SECTOR, 128)
    data_start = 60
    catalog = []
    attributes = []
    overflow = []

    def install(data, start=None):
        nonlocal data_start
        if start is None:
            start = data_start
            data_start += (len(data) + SECTOR - 1) // SECTOR
        end = start * SECTOR + len(data)
        assert end <= len(image)
        image[start * SECTOR:end] = data
        return fork(len(data), [(start, (len(data) + SECTOR - 1) // SECTOR)])

    def entry(cnid, parent, name, *, mode=0o100644, finder=b"", linked=0,
              data=bytes(80), resource=bytes(80), compressed=False):
        directory = stat.S_ISDIR(mode)
        payload = bytearray(88 if directory else 248)
        struct.pack_into(">H", payload, 0, 1 if directory else 2)
        struct.pack_into(">I", payload, 8, cnid)
        struct.pack_into(">I", payload, 16, MTIME + 2082844800)
        struct.pack_into(">BHI", payload, 41, 0x20 if compressed else 0, mode, linked)
        payload[48:48 + len(finder)] = finder
        if not directory:
            payload[88:168] = data
            payload[168:248] = resource
        key = struct.pack(">IH", parent, len(name.encode("utf-16-be")) // 2)
        catalog.append((key + name.encode("utf-16-be"), payload))

    def compressed(cnid, kind, size, inline=b"", resource=bytes(80)):
        name = "com.apple.decmpfs"
        key = struct.pack(">HIIH", 0, cnid, 0, len(name)) + name.encode("utf-16-be")
        value = b"fpmc" + struct.pack("<IQ", kind, size) + inline
        attributes.append((key, struct.pack(">4I", 0x10, 0, 0, len(value)) + value))
        entry(cnid, 2, f"compression-{kind}", resource=resource, compressed=True)

    def resource_zlib(chunks):
        offset = 4 + 8 * len(chunks)
        table = bytearray(struct.pack("<I", len(chunks)))
        for chunk in chunks:
            table += struct.pack("<II", offset, len(chunk))
            offset += len(chunk)
        payload = bytes(table) + b"".join(chunks)
        header = struct.pack(">4I", 256, 260 + len(payload), 4 + len(payload), 0)
        return header.ljust(256, b"\0") + struct.pack(">I", len(payload)) + payload

    def resource_offsets(*chunks):
        offsets = [4 * (len(chunks) + 1)]
        for chunk in chunks:
            offsets.append(offsets[-1] + len(chunk))
        return struct.pack(f"<{len(offsets)}I", *offsets) + b"".join(chunks)

    entry(2, 1, "Synthetic", mode=0o40755)
    entry(16, 2, "A.app", mode=0o40555)
    entry(17, 16, "Contents", mode=0o40750)
    entry(18, 17, "Info.plist", data=install(plistlib.dumps({
        "CFBundleIdentifier": "org.example.synthetic", "CFBundleExecutable": "Start",
    }, fmt=plistlib.FMT_BINARY)))
    entry(19, 17, "Start", mode=0o100751, data=install(b"#!/bin/sh\n"))
    entry(20, 2, "link", finder=b"slnkrhap", data=install(b"../outside"))
    entry(21, 2, "\0\0\0\0HFS+ Private Data", mode=0o40755)
    entry(22, 21, "iNode42", data=install(b"hardlinked data"))
    entry(23, 2, "first", finder=b"hlnkhfs+", linked=42)
    entry(24, 2, "second", finder=b"hlnkhfs+", linked=42)
    entry(25, 2, ".DS_Store", data=install(b"metadata"))
    entry(26, 2, "\U0001f34f/e\u0301", data=install(b"UTF-16 name"))
    entry(27, 17, "Nested.app", mode=0o40755)
    entry(28, 27, "Contents", mode=0o40755)
    entry(29, 28, "Info.plist", data=install(plistlib.dumps({
        "CFBundleIdentifier": "org.example.nested", "CFBundleExecutable": "Nested",
    })))

    extents = [(100 + 2 * index, 1) for index in range(9)]
    for index, (start, _) in enumerate(extents):
        install(bytes([index]) * SECTOR, start)
    entry(30, 2, "fragmented", data=fork(9 * SECTOR - 5, extents[:8], 9))
    overflow.append((struct.pack(">BBII", 0, 0, 30, 8), extent_record(extents[8:])))

    compressed(31, 3, 200, zlib.compress(b"Z" * 200))
    compressed(32, 4, 65540, resource=install(
        resource_zlib([zlib.compress(b"R" * 65536), b"\xfftail"])))
    compressed(33, 7, len(LZVN_TEXT), LZVN_STREAM[12:-4])
    # A short LZVN resource block and a short LZFSE resource block.
    compressed(34, 8, len(LZVN_TEXT), resource=install(resource_offsets(LZVN_STREAM[12:-4])))
    compressed(35, 11, len(LZFSE_TEXT), LZFSE_STREAM)
    compressed(36, 12, len(LZFSE_TEXT), resource=install(resource_offsets(LZFSE_STREAM)))
    if unsafe_name is not None:
        entry(40, 2, unsafe_name, data=install(b"invalid path"))

    image[1024 + 192:1024 + 272] = install(btree(overflow, 512), 34)
    image[1024 + 272:1024 + 352] = install(btree(catalog, 4096, 0xbc, split=12), 8)
    image[1024 + 352:1024 + 432] = install(btree(attributes, 4096), 36)
    return image


class DecoderTest(unittest.TestCase):
    def test_adc(self):
        data = b"\x82abc\x00\x02\x41\x00\x02"
        self.assertEqual(DMGX["decode_adc"](data, 11), b"abcabcabcab")
        with self.assertRaises(DMGX["ImageError"]):
            DMGX["decode_adc"](b"\x00\x00", 3)

    def test_lzfse_streams(self):
        raw = b"bvx-\x04\0\0\0testbvx$"
        header = bytearray(LZFSE_STREAM[:32])
        full_header_size = struct.unpack_from("<I", header, 24)[0]
        struct.pack_into("<I", header, 24, len(header))
        shared_tables = LZFSE_STREAM[:-4] + header + LZFSE_STREAM[full_header_size:]
        for data, expected in ((raw, b"test"), (LZVN_STREAM, LZVN_TEXT),
                               (LZFSE_STREAM, LZFSE_TEXT),
                               (LZFSE_V1_STREAM, LZFSE_TEXT),
                               (shared_tables, LZFSE_TEXT * 2),
                               (raw[:-4] + LZFSE_STREAM, b"test" + LZFSE_TEXT)):
            with self.subTest(magic=data[:4]):
                self.assertEqual(DMGX["decode_lzfse"](data, len(expected)), expected)
        self.assertEqual(DMGX["decode_lzvn"](LZVN_STREAM[12:-4], len(LZVN_TEXT)), LZVN_TEXT)
        with self.assertRaises(DMGX["ImageError"]):
            DMGX["decode_lzfse"](LZFSE_STREAM[:-4], len(LZFSE_TEXT))
        with self.assertRaises(DMGX["ImageError"]):
            DMGX["decode_lzfse"](LZVN_STREAM, len(LZVN_TEXT) - 1)

    def test_udif(self):
        zlib_sector = b"z" * SECTOR
        raw_sector = bytes(range(256)) * 2
        xz_sector = b"x" * SECTOR
        bz_sector = b"b" * SECTOR
        chunks = [(0x80000005, 0, 1, zlib.compress(zlib_sector)),
                  (1, 1, 1, raw_sector), (0x7ffffffe, 9, 0, b""),
                  (0, 2, 1, b""), (2, 3, 1, b""), (0x80000008, 4, 1, lzma.compress(xz_sector))]
        image = make_udif([(0, 5, chunks),
                           (6, 1, [(0x80000006, 0, 1, bz2.compress(bz_sector))])], 7)
        with tempfile.TemporaryFile() as file:
            file.write(image)
            file.flush()
            disk = DMGX["disk_reader"](file)
            self.assertEqual(disk.chunk_types[0x7ffffffe], 1)
            expected = zlib_sector + raw_sector + bytes(SECTOR * 2) + xz_sector + bytes(SECTOR) + bz_sector
            self.assertEqual(disk.read(500, 3000), expected[500:3500])
            self.assertEqual(disk.read(0, len(expected)), expected)
            self.assertEqual(len(disk.cache), 3)

    def test_large_chunk_spool(self):
        size = 3 * 1024 * 1024
        plain = b"chunk!!?" * (size // 8)
        vectors = [(0x80000005, zlib.compress(plain), plain),
                   (0x80000006, bz2.compress(plain), plain),
                   (0x80000008, lzma.compress(plain), plain)]
        # A much larger uncompressed LZFSE block followed by a real LZVN block.
        prefix = bytes(size - len(LZVN_TEXT))
        lzfse = struct.pack("<4sI", b"bvx-", len(prefix)) + prefix + LZVN_STREAM
        vectors.append((0x80000007, lzfse, prefix + LZVN_TEXT))
        adc_match = b"\x7f\0\0"  # Append 67 copies of the previous byte.
        repeat, extra = divmod(size - 1, 67)
        adc = b"\x80a" + adc_match * repeat
        adc += bytes([0x40 + extra - 4, 0, 0])
        vectors.append((0x80000004, adc, b"a" * size))
        sectors = size // SECTOR
        chunks = [(kind, index * sectors, sectors, packed)
                  for index, (kind, packed, _) in enumerate(vectors)]
        total = sectors * len(chunks)
        with tempfile.NamedTemporaryFile() as file:
            file.write(make_udif([(0, total, chunks)], total))
            file.flush()
            with DMGX["open_disk"](file.name) as disk:
                disk.CACHE_BYTES = size - 1
                for index, (kind, _, expected) in enumerate(vectors):
                    with self.subTest(kind=kind):
                        offset = index * size
                        self.assertEqual(disk.read(offset, size), expected)
                        self.assertEqual(disk.read(offset + size - 100, 100), expected[-100:])
                        self.assertFalse(disk.cache)
                spool_file = disk.spooled[1].file
            self.assertTrue(spool_file.closed)


class FilesystemTest(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.image = self.root / "synthetic.img"
        self.image.write_bytes(hfs_volume())

    def run_tool(self, command, *args, check=True):
        return subprocess.run([str(SCRIPT), command, str(self.image), *map(str, args)],
                              text=True, capture_output=True, check=check)

    def test_info_list_and_bundles(self):
        self.assertIn("Filesystem: HFSX", self.run_tool("info").stdout)
        self.assertIn("Synthetic", self.run_tool("info").stdout)
        listed = self.run_tool("list").stdout.splitlines()
        self.assertIn("A.app/Contents/Start", listed)
        self.assertIn(".DS_Store", listed)
        self.assertNotIn(".DS_Store", self.run_tool("list", "--no-metadata").stdout.splitlines())
        self.assertIn("\U0001f34f:e\u0301", listed)
        self.assertNotIn("iNode", "\n".join(listed))
        self.assertEqual(self.run_tool("find-apps").stdout.splitlines(), [
            "A.app\tStart\torg.example.synthetic",
            "A.app/Contents/Nested.app\tNested\torg.example.nested",
        ])

    def test_extract(self):
        out = self.root / "out"
        self.run_tool("extract", out)
        tool = out / "A.app" / "Contents" / "Start"
        self.assertEqual(tool.read_bytes(), b"#!/bin/sh\n")
        self.assertEqual(stat.S_IMODE(tool.stat().st_mode), 0o751)
        self.assertEqual(stat.S_IMODE((out / "A.app").stat().st_mode), 0o555)
        self.assertEqual(int(tool.stat().st_mtime), MTIME)
        self.assertEqual(int((out / "A.app").stat().st_mtime), MTIME)
        self.assertEqual(os.readlink(out / "link"), "../outside")
        self.assertEqual((out / "first").read_bytes(), b"hardlinked data")
        self.assertTrue((out / "first").samefile(out / "second"))
        self.assertEqual((out / ".DS_Store").read_bytes(), b"metadata")
        self.assertEqual((out / "fragmented").read_bytes(),
                         b"".join(bytes([index]) * SECTOR for index in range(9))[:-5])
        for kind, expected in ((3, b"Z" * 200), (4, b"R" * 65536 + b"tail"),
                               (7, LZVN_TEXT), (8, LZVN_TEXT),
                               (11, LZFSE_TEXT), (12, LZFSE_TEXT)):
            self.assertEqual((out / f"compression-{kind}").read_bytes(), expected)
        filtered = self.root / "filtered"
        self.run_tool("extract", "--no-metadata", filtered)
        self.assertFalse((filtered / ".DS_Store").exists())

    def test_unsafe_paths(self):
        outside = self.root / "outside"
        outside.mkdir()
        output = self.root / "out"
        output.mkdir()
        (output / "A.app").symlink_to(outside, target_is_directory=True)
        self.assertNotEqual(self.run_tool("extract", output, check=False).returncode, 0)
        root_link = self.root / "root-link"
        root_link.symlink_to(outside, target_is_directory=True)
        self.assertNotEqual(self.run_tool("extract", str(root_link) + "/", check=False).returncode, 0)
        self.assertEqual(list(outside.iterdir()), [])
        self.image.write_bytes(hfs_volume(unsafe_name=".."))
        unsafe = self.run_tool("extract", self.root / "other", check=False)
        self.assertNotEqual(unsafe.returncode, 0)
        self.assertIn("unsafe HFS+ path component", unsafe.stderr)

    def test_apfs_error(self):
        image = bytearray(4096)
        image[32:36] = b"NXSB"
        self.image.write_bytes(image)
        result = self.run_tool("list", check=False)
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("APFS images are not supported yet", result.stderr)

    def test_partition_schemes(self):
        volume = hfs_volume()
        apm = bytearray(8 * SECTOR) + volume
        struct.pack_into(">2sH", apm, 0, b"ER", 512)
        struct.pack_into(">2s2xIII32s32s", apm, SECTOR,
                         b"PM", 1, 8, 128, b"Volume", b"Apple_HFS")
        self.image.write_bytes(apm)
        self.assertIn("Partition scheme: APM", self.run_tool("info").stdout)

        gpt = bytearray(8 * SECTOR) + volume
        gpt[SECTOR:SECTOR + 8] = b"EFI PART"
        struct.pack_into("<QII", gpt, SECTOR + 72, 2, 1, 128)
        guid = UUID("48465300-0000-11aa-aa11-00306543ecac")
        gpt[2 * SECTOR:2 * SECTOR + 16] = guid.bytes_le
        struct.pack_into("<QQ", gpt, 2 * SECTOR + 32, 8, 135)
        chunks = [(0x80000005, 0, len(gpt) // SECTOR, zlib.compress(gpt))]
        self.image.write_bytes(make_udif([(0, len(gpt) // SECTOR, chunks)], len(gpt) // SECTOR))
        info = self.run_tool("info").stdout
        self.assertIn("Container: UDIF", info)
        self.assertIn("Partition scheme: GPT", info)
        self.assertIn("Filesystem: HFSX", info)


@unittest.skipUnless(os.environ.get("DMGX_TEST_IMAGE"), "set DMGX_TEST_IMAGE to test a real image")
class RealImageTest(unittest.TestCase):
    def test_commands(self):
        image = os.environ["DMGX_TEST_IMAGE"]
        with tempfile.TemporaryDirectory(prefix="dmgx-integration-") as directory:
            for args in (("info", image), ("list", image), ("find-apps", image),
                         ("extract", image, directory)):
                result = subprocess.run([str(SCRIPT), *args], capture_output=True)
                self.assertEqual(result.returncode, 0, f"{args[0]} failed")
            self.assertTrue(any(Path(directory).iterdir()))


if __name__ == "__main__":
    unittest.main()
